            var tb = Math.min(1, rise / 0.1) * Math.max(0, Math.min(1, (0.6 * sigma - bt) / (0.25 * sigma)));
            bench[qb] = tb;
            var yc = EMO[3][1];
            col[qb * 3] = col[qb * 3] * (1 - tb) + yc[0] * tb;
            col[qb * 3 + 1] = col[qb * 3 + 1] * (1 - tb) + yc[1] * tb;
